 p=O/name
 if p.suffix=='.jsonl':value=[json.loads(l) for l in p.read_text(encoding='utf-8').splitlines() if l.strip()]
 else:value=json.loads(p.read_text(encoding='utf-8'))
 dest=redacted/(name.replace('.jsonl','.json'));dump(dest,redact(value));provenance.append(dict(original=name,original_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),export=str(dest.relative_to(R)),export_sha256=hashlib.sha256(dest.read_bytes()).hexdigest(),redaction='Named GM-only field values; original player input/publication strings intact'))
