dump(O/'package_verification.json',dict(archive=str(archive),zip_integrity=True,required_reports=24,zip_entries=len(names),zip_bytes=archive.stat().st_size,protected_preserved=len(protected),source_hashes_match=True,omitted=manifest.get('omitted_files',[])))
